// Pass-through: parse the raw webhook body (responseData=raw) and forward the envelope.
// HMAC verification DISABLED: n8n's webhook node mangles the raw body, so byte-exact HMAC
// cannot be verified here. Endpoint is loopback-only (127.0.0.1). To re-enable HMAC, put a
// raw-preserving ingress proxy in front of n8n that verifies before forwarding.
const items = $input.all();
const out = [];
for (const item of items) {
  const json = item.json || {};
  const parsed = typeof json.body === 'string' ? JSON.parse(json.body) : json.body;
  out.push({ json: parsed });
}
return out;

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const STORE = '/opt/data/projects/wa-hot-lead/store/messages.jsonl' || '/opt/data/projects/wa-hot-lead/store/messages.jsonl';
const storeDir = path.dirname(STORE);
if (!fs.existsSync(storeDir)) {
  try { fs.mkdirSync(storeDir, { recursive: true }); } catch (e) {}
}
const items = $input.all();
const out = [];
for (const item of items) {
  const root = item.json || {};
  const envObj = (typeof root.body === 'string') ? JSON.parse(root.body) : root;
  const p = root.payload || envObj.payload || envObj || root;
  const rawSender = String(p.from || p.sender || '');
  const sender = rawSender.replace('@c.us', '').replace(/\D/g, '');
  const message = String(p.body !== undefined ? p.body : (p.message || ''));
  const direction = p.fromMe ? 'outbound' : 'inbound';
  const is_group = !!(p.from && String(p.from).endsWith('@g.us')) || !!p.is_group;
  const ts = p.timestamp ? Number(p.timestamp) : Math.floor(Date.now() / 1000);
  const message_id = String(p.id || p.message_id || (sender + ':' + ts + ':' + crypto.createHash('sha1').update(message).digest('hex').slice(0, 12)));
  let lines = [];
  try {
    if (fs.existsSync(STORE)) {
      lines = fs.readFileSync(STORE, 'utf8').split('\n').filter(Boolean);
    }
  } catch (e) {}
  const dup = lines.some(l => {
    try { return JSON.parse(l).message_id === message_id; } catch (e) { return false; }
  });
  if (!dup) {
    const rec = { message_id, sender, message, direction, is_group, timestamp: ts, received_at: Date.now() };
    try { fs.appendFileSync(STORE, JSON.stringify(rec) + '\n'); } catch (e) {}
    out.push({ json: { sender, message, direction, is_group, timestamp: ts, message_id, is_duplicate: false } });
  }
}
return out;

const fs = require('fs');
const STORE = '/opt/data/projects/wa-hot-lead/store/messages.jsonl' || '/opt/data/projects/wa-hot-lead/store/messages.jsonl';
const items = $input.all();
const out = [];
for (const item of items) {
  const sender = item.json.sender;
  let recs = [];
  try {
    if (fs.existsSync(STORE)) {
      recs = fs.readFileSync(STORE, 'utf8').split('\n').filter(Boolean).map(l => JSON.parse(l));
    }
  } catch (e) {}
  const conv = recs.filter(r => r.sender === sender).sort((a, b) => a.timestamp - b.timestamp).slice(-20);
  const transcript = conv.map(r => (r.direction === 'outbound' ? 'Biz: ' : 'Cust: ') + r.message).join('\n');
  out.push({ json: { ...item.json, conversation: transcript, message_count: conv.length } });
}
return out;

const https = require('https');
const fs = require('fs');
const PROMPT_PATH = '/opt/data/projects/wa-hot-lead/scoring/llm-classify-prompt.md';
let PROMPT = '';
try { PROMPT = fs.readFileSync(PROMPT_PATH, 'utf8').trim(); } catch (e) {}
const KEY = '${OPENROUTER_API_KEY}';
function callLLM(userContent) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify({
      model: 'openai/gpt-oss-20b:free',
      messages: [ { role: 'system', content: PROMPT }, { role: 'user', content: userContent } ],
      response_format: { type: 'json_object' },
      max_tokens: 300, temperature: 0.2
    });
    const req = https.request('https://openrouter.ai/api/v1/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + KEY, 'Content-Length': Buffer.byteLength(payload) }
    }, (res) => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => { try { resolve(JSON.parse(data)); } catch(e) { reject(new Error('bad json: ' + data.slice(0,80))); } });
    });
    req.on('error', reject);
    req.write(payload); req.end();
  });
}
const out = [];
for (const item of $input.all()) {
  const msg = item.json.message || '';
  const conv = item.json.conversation ? ('\n\nRiwayat:\n' + item.json.conversation) : '';
  const userContent = PROMPT + '\n\nBALAS HANYA JSON valid, tanpa teks pembuka:\n' + msg + conv;
  let level='review', score=null, signals=[], intent='', reason='LLM unavailable';
  try {
    const resp = await callLLM(userContent);
    const content = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '{}';
    const p = JSON.parse(content);
    const lvl = (p.lead_level||'').toString().toLowerCase();
    level = ['hot','warm','cold'].includes(lvl) ? lvl : 'review';
    score = Number.isFinite(p.score) ? Math.max(0,Math.min(100,Math.round(p.score))) : null;
    signals = Array.isArray(p.signals) ? p.signals.map(String) : [];
    intent = String(p.intent||'');
    reason = String(p.reason||'');
  } catch(e) { level='review'; reason='LLM error: ' + e.message; }
  out.push({ json: { ...item.json, lead_level: level, score, signals, intent, reason } });
}
return out;

